import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Attendance — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/attendance"}]]},"headers":[],"relativePath":"user-guide/attendance.md","filePath":"user-guide/attendance.md","lastUpdated":1786636213000}'),o={name:"user-guide/attendance.md"};function r(i,e,l,c,d,g){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="attendance-—-user-guide" tabindex="-1">Attendance — User Guide <a class="header-anchor" href="#attendance-—-user-guide" aria-label="Permalink to &quot;Attendance — User Guide&quot;">​</a></h1><p>Enable <strong>Employees</strong> first, then install <strong>Attendance</strong> from Marketplace (free). Nav appears under <strong>HR</strong>.</p><h2 id="office-hours" tabindex="-1">Office hours <a class="header-anchor" href="#office-hours" aria-label="Permalink to &quot;Office hours&quot;">​</a></h2><p>When Attendance is installed, open <strong>Settings → Attendance</strong> to set:</p><ul><li>Office start / end time (local to <strong>Settings → General → Timezone</strong>)</li><li>Grace period (minutes) — check-ins after start + grace are marked <strong>Late</strong></li><li>Work week days (used for payroll working-day calendars)</li></ul><p>Attendance uses the same workspace <strong>Timezone</strong> as Daily Reminder Time, meetings, and task/follow-up due dates (for example <code>Asia/Karachi</code>). There is no separate attendance timezone. See <a href="/user-guide/tenant-settings#workspace-timezone">Tenant Settings — Workspace timezone</a>.</p><h2 id="login-check-in" tabindex="-1">Login check-in <a class="header-anchor" href="#login-check-in" aria-label="Permalink to &quot;Login check-in&quot;">​</a></h2><p>When a workspace user who is linked to an <strong>active</strong> employee signs in, the system creates or updates today’s attendance (workspace-local “today” and check-in clock):</p><ul><li>First successful login of the day sets <strong>check-in</strong> and status (<strong>Present</strong> or <strong>Late</strong>)</li><li>The check-in <strong>IP address</strong> is stored from the request</li><li>The browser may also send <strong>GPS coordinates</strong> (if the user allows location access); denied/unavailable location still allows login</li><li>Later logins the same day do not change check-in</li><li>Check-out remains manual on the Attendance page (IP/coordinates can be stored when provided)</li><li>On the attendance detail sheet, stored coordinates open in <strong>Google Maps</strong> via a standard maps URL (no Google API integration)</li></ul><p>Users without a linked employee are skipped. If Attendance is not installed, login is unchanged.</p><h2 id="self-service-staff" tabindex="-1">Self-service (staff) <a class="header-anchor" href="#self-service-staff" aria-label="Permalink to &quot;Self-service (staff)&quot;">​</a></h2><p>Linked employees with Attendance create/update permission can:</p><ol><li>Open <strong>Attendance</strong> (you only see <strong>your</strong> records).</li><li>Use <strong>Check in</strong> if login did not already create today’s check-in.</li><li>Use <strong>Check out</strong> at the end of the day (stores the current time).</li><li>Use <strong>Mark attendance</strong> for a fuller form (own employee only). Check-in is set on create (or login auto check-in); staff can only add <strong>check-out</strong> and notes afterward. Managers can correct times later.</li></ol><p>Staff cannot change attendance <strong>status</strong> (Present / Absent / etc.). Managers and admins set or correct status when needed.</p><h2 id="managers-and-admins" tabindex="-1">Managers and admins <a class="header-anchor" href="#managers-and-admins" aria-label="Permalink to &quot;Managers and admins&quot;">​</a></h2><p>Managers and admins can:</p><ol><li>View everyone’s records and KPI stats.</li><li><strong>Record attendance</strong> for any employee and date (one record per employee per day).</li><li>Edit check-in / check-out times, status, and notes for corrections.</li></ol><h2 id="daily-records" tabindex="-1">Daily records <a class="header-anchor" href="#daily-records" aria-label="Permalink to &quot;Daily records&quot;">​</a></h2><ol><li>Open <strong>Attendance</strong>.</li><li>Create or complete a record for the day (staff: self only; managers: any employee).</li><li>Optionally set check-in and check-out times (managers may edit either).</li><li>Choose status: Present, Absent, Half day, Remote, or Late.</li><li>Add notes if needed.</li></ol><p>Status badges use fixed colors so presence is easy to scan: <strong>Present</strong> (green), <strong>Late</strong> (red), <strong>Absent</strong> (slate), <strong>Half day</strong> (amber), <strong>Remote</strong> (blue). The same colors appear in the list table and the detail sheet.</p><h2 id="list-stats" tabindex="-1">List &amp; stats <a class="header-anchor" href="#list-stats" aria-label="Permalink to &quot;List &amp; stats&quot;">​</a></h2><ul><li>Filter by employee, date range, and status</li><li>KPI cards show totals including late</li><li>Soft-deleted records can be restored or permanently removed when you have permission</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use <strong>Remote</strong> for WFH days that still count as present for workforce reporting.</li><li>Half-day is a status flag in this MVP — it does not auto-split leave balances.</li><li>Link employees to users (or create users with <strong>Create employee record</strong>) so login check-in works.</li></ul>',24)])])}const u=t(o,[["render",r]]);export{m as __pageData,u as default};
